                }}
                className="bg-transparent text-[#ffd86b] text-xs font-mono font-bold focus:outline-none cursor-pointer max-w-[190px] truncate"
                title="Filter to include songs from this playlist or channel"
              >
                <option value="ALL" className="bg-[#120f18] text-white">
                  🌐 All Playlists (Catalog)
                </option>

                {/* 1. Custom Playlists */}
                <optgroup label="⭐ Custom Playlists" className="bg-[#120f18] text-[#ffd86b] font-bold">
                  <option value="__MANAGE_PLAYLISTS__" className="bg-[#1c1424] text-[#ffd86b]">
