                      ▶ Stream All Approved ({approvedChannels.reduce((sum, c) => sum + c.count, 0).toLocaleString()} songs)
                    </option>
                  )}
                  {approvedChannels.map((ch) => (
                    <option key={ch.name} value={ch.name} className="bg-[#120f18] text-emerald-100">
                      {ch.name} ({ch.count.toLocaleString()} songs{ch.avg_hazard ? ` • ${ch.avg_hazard}` : ''})
                    </option>
                  ))}
