                <optgroup label={`🟡 Cleaning Playlists (${cleaningChannels.length})`} className="bg-[#120f18] text-amber-400 font-bold">
                  {cleaningChannels.length > 1 && (
                    <option value="STATUS:cleaning" className="bg-[#261f0a] text-amber-300 font-bold">
                      ▶ Stream All Cleaning ({cleaningChannels.reduce((sum, c) => sum + c.count, 0).toLocaleString()} songs)
                    </option>
                  )}
                  {cleaningChannels.map((ch) => (
                    <option key={ch.name} value={ch.name} className="bg-[#120f18] text-amber-100">
                      {ch.name} ({ch.count.toLocaleString()} songs{ch.avg_hazard ? ` • ${ch.avg_hazard}` : ''})
                    </option>
