                className="flex items-center gap-1 text-[11px] font-mono px-2.5 py-1 rounded-lg bg-gradient-to-r from-[#291e07] to-[#1a1424] hover:brightness-125 border border-[#524124] text-[#ffd86b] transition cursor-pointer"
              >
