                if (selectedChannel === 'STATUS:cleaning') return `🟡 All Cleaning Playlists (${cleaningChannels.length} channels)`;
                if (selectedChannel === 'STATUS:raw') return `🔴 All Raw Playlists (${rawChannels.length} channels)`;
