94	    );
95	  };
96	
97	  const toggleTimeblock = (tbId: string) => {
98	    setSelectedTimeblocks((prev) =>
99	      prev.includes(tbId) ? prev.filter((t) => t !== tbId) : [...prev, tbId]
100	    );
101	  };
102	
103	  const filteredChannels = useMemo(() => {
104	    if (!channelSearchQuery.trim()) return channelList;
105	    const q = channelSearchQuery.toLowerCase().trim();
106	    return channelList.filter((ch) => ch.name.toLowerCase().includes(q));
107	  }, [channelList, channelSearchQuery]);
108	
109	  const totalTracksInSelection = useMemo(() => {
110	    const chSet = new Set(selectedChannels);
111	    return channelList
112	      .filter((ch) => chSet.has(ch.name))
113	      .reduce((sum, ch) => sum + ch.count, 0);
114	  }, [channelList, selectedChannels]);
115	
116	  const handleSave = async () => {
117	    if (!name.trim()) {
118	      setErrorMessage('Playlist title is required');
119	      return;
120	    }
121	    if (selectedChannels.length === 0) {
122	      setErrorMessage('Please select at least one channel for this playlist');
123	      return;
124	    }
125	
126	    setIsSaving(true);
127	    setErrorMessage(null);
128	
129	    try {
130	      const saved = await saveCustomPlaylist(projectId, {
131	        id: editingPlaylistId || undefined,
132	        name: name.trim(),
133	        emoji,
134	        description: description.trim(),
135	        channels: selectedChannels,
136	        compatible_timeblocks: selectedTimeblocks,
137	      });
138	
139	      if (editingPlaylistId) {
140	        updateCustomPlaylist(saved);
141	      } else {
142	        addCustomPlaylist(saved);
143	      }
144	
145	      setMode('list');
146	      if (onSelectPlaylist) {
147	        onSelectPlaylist(saved.id);
148	      }
149	    } catch (err: any) {
150	      setErrorMessage(err.message || 'Failed to save playlist');
151	    } finally {
152	      setIsSaving(false);
153	    }
154	  };
155	
156	  const handleDelete = async (plId: string) => {
157	    const playlist = customPlaylists.find((p) => p.id === plId);
158	    if (!playlist) return;
159	
160	    // Calculate total songs across all member channels
161	    const totalSongs = playlist.channels.reduce((sum, chName) => {
162	      const ch = channelList.find((c) => c.name === chName);
163	      return sum + (ch?.count || 0);
164	    }, 0);
165	
166	    // Confirmation dialog with purge details
167	    const confirmed = confirm(
168	      `⚠️ PLAYLIST DELETION WITH CHANNEL PURGE\n\n` +
169	      `Delete playlist "${playlist.name}"?\n\n` +
170	      `This will:\n` +
171	      `• Delete the playlist federation\n` +
172	      `• PURGE all ${totalSongs.toLocaleString()} songs from ${playlist.channels.length} channel(s):\n` +
173	      `  ${playlist.channels.join(', ')}\n\n` +
174	      `This is a soft-reboot: you can re-curl these channels with refined filters.\n\n` +
175	      `Proceed?`
176	    );
177	
178	    if (!confirmed) return;
179	
180	    try {
181	      // Step 1: Purge all songs from member channels
182	      const purgePromises = playlist.channels.map(async (chName) => {
183	        const ch = channelList.find((c) => c.name === chName);
184	        if (ch) {
185	          try {
186	            await purgeChannelSongs(projectId, ch.name, ch.channel_id);
187	          } catch (err) {
188	            console.warn(`[PlaylistDelete] Failed to purge channel ${chName}:`, err);
189	          }
190	        }
191	      });
192	
193	      await Promise.all(purgePromises);
194	
195	      // Step 2: Delete the playlist itself
196	      await deleteCustomPlaylist(projectId, plId);
197	      removeCustomPlaylist(plId);
198	
199	      if (mode === 'edit' && editingPlaylistId === plId) {
200	        setMode('list');
201	      }
202	    } catch (err) {
203	      console.error('[PlaylistDelete] Failed to delete playlist and purge channels:', err);
204	    }
205	  };
206	
207	  return (
208	    <ModalContainer
209	      isOpen={isOpen}
210	      onClose={onClose}
211	      title={mode === 'list' ? 'Custom Playlists' : editingPlaylistId ? 'Edit Playlist' : 'New Playlist'}
212	      subtitle={
213	        mode === 'list'
214	          ? 'Federate multiple channels into thematic listening streams'
215	          : 'Combine channels under a shared musical style and timeblock'
216	      }
217	      icon={<Crown className="w-5 h-5 text-[#ffd86b]" />}
218	      maxWidth="xl"
219	    >
220	      {mode === 'list' ? (
221	        <div className="space-y-4 text-left">
222	          {/* Top Action */}
223	          <div className="flex items-center justify-between">
224	            <span className="text-xs font-mono text-[#8c7a9e]">
225	              Active Playlists ({customPlaylists.length})
226	            </span>
227	            <SharedButton variant="primary" size="sm" onClick={startCreating} className="flex items-center gap-1.5">
228	              <Plus className="w-3.5 h-3.5 text-black" />
229	              <span>New Playlist</span>
230	            </SharedButton>
231	          </div>
232	
233	          {/* List of Playlists */}
234	          {customPlaylists.length === 0 ? (
235	            <div className="p-8 rounded-xl bg-[#140f1c] border border-[#2b2238] text-center space-y-2">
236	              <Sparkles className="w-8 h-8 text-[#ffd86b] mx-auto opacity-70" />
237	              <p className="text-sm font-cinzel font-bold text-[#f5f0e8]">No Custom Playlists Yet</p>
238	              <p className="text-xs text-[#8c7a9e] max-w-sm mx-auto">
239	                Group your favorite channels together (e.g., HOYO-MiX + NCS) to create themed listening streams.
240	              </p>
241	            </div>
242	          ) : (
243	            <div className="space-y-2 max-h-[360px] overflow-y-auto pr-1">
244	              {customPlaylists.map((pl) => {
245	                const pooledTracks = channelList
246	                  .filter((ch) => pl.channels.includes(ch.name))
247	                  .reduce((sum, ch) => sum + ch.count, 0);
248	
249	                return (
250	                  <div
251	                    key={pl.id}
252	                    className="p-3.5 rounded-xl bg-[#15101f] hover:bg-[#1c152a] border border-[#2e243d] hover:border-[#d4af37]/60 transition flex items-center justify-between gap-3 group"
253	                  >
254	                    <div
255	                      className="flex items-center gap-3 cursor-pointer flex-1 min-w-0"
256	                      onClick={() => {
257	                        if (onSelectPlaylist) {
258	                          onSelectPlaylist(pl.id);
259	                          onClose();
260	                        }
261	                      }}
262	                    >
263	                      <span className="text-2xl flex-shrink-0">{pl.emoji || '🎵'}</span>
264	                      <div className="truncate">
265	                        <h4 className="text-sm font-bold text-white group-hover:text-[#ffd86b] transition truncate">
266	                          {pl.name}
267	                        </h4>
268	                        <p className="text-[11px] font-mono text-[#8c7a9e] truncate">
269	                          {pl.channels.length} channel{pl.channels.length > 1 ? 's' : ''} •{' '}
270	                          <span className="text-[#ffd86b] font-bold">{pooledTracks.toLocaleString()}</span> songs
271	                          {pl.description ? ` • ${pl.description}` : ''}
272	                        </p>
273	                      </div>
274	                    </div>
275	
276	                    <div className="flex items-center gap-1.5 flex-shrink-0">
277	                      <button
278	                        type="button"
279	                        onClick={() => startEditing(pl)}
280	                        title="Edit Playlist Channels"
281	                        className="p-1.5 rounded-lg bg-[#20172e] hover:bg-[#2e2042] text-[#8c7a9e] hover:text-white border border-[#3b2b52] transition cursor-pointer"
282	                      >
283	                        <Edit3 className="w-3.5 h-3.5" />
284	                      </button>
285	                      <button
286	                        type="button"
287	                        onClick={() => handleDelete(pl.id)}
288	                        title="Delete Playlist"
289	                        className="p-1.5 rounded-lg bg-rose-950/40 hover:bg-rose-900/60 text-rose-300 hover:text-rose-100 border border-rose-800/50 transition cursor-pointer"
290	                      >
291	                        <Trash2 className="w-3.5 h-3.5" />
292	                      </button>
293	                    </div>
294	                  </div>
295	                );
296	              })}
297	            </div>
298	          )}
299	        </div>
300	      ) : (
301	        /* Edit / Create Form */
302	        <div className="space-y-4 text-left">
303	          <button
304	            type="button"
305	            onClick={() => setMode('list')}
306	            className="inline-flex items-center gap-1 text-xs font-mono text-[#8c7a9e] hover:text-[#ffd86b] transition cursor-pointer mb-1"
307	          >
308	            <ArrowLeft className="w-3.5 h-3.5" />
309	            <span>Back to Playlists List</span>
310	          </button>
311	
312	          {errorMessage && (
313	            <div className="p-2.5 rounded-lg bg-rose-950/80 border border-rose-600/70 text-rose-200 text-xs font-mono">
314	              ⚠️ {errorMessage}
315	            </div>
316	          )}
317	
318	          {/* Name & Emoji */}
319	          <div className="grid grid-cols-1 sm:grid-cols-4 gap-2.5">
320	            <div className="sm:col-span-3 space-y-1">
321	              <label className="text-xs font-mono text-[#8c7a9e]">Playlist Title *</label>
322	              <input
323	                type="text"
324	                autoFocus
325	                placeholder="e.g. Epic Battle Orchestral"
326	                value={name}
327	                onChange={(e) => setName(e.target.value)}
328	                className="w-full bg-[#171320] border border-[#3b2b4d] focus:border-[#ffd86b] rounded-xl px-3 py-2 text-sm text-white focus:outline-none transition"
329	              />
330	            </div>
331	
332	            <div className="space-y-1">
333	              <label className="text-xs font-mono text-[#8c7a9e]">Icon Emoji</label>
334	              <div className="flex items-center gap-1">
335	                <input
336	                  type="text"
337	                  maxLength={2}
338	                  value={emoji}
339	                  onChange={(e) => setEmoji(e.target.value)}
340	                  className="w-14 text-center bg-[#171320] border border-[#3b2b4d] focus:border-[#ffd86b] rounded-xl py-2 text-lg text-white focus:outline-none transition"
341	                />
342	              </div>
343	            </div>
344	          </div>
345	
346	          {/* Preset Emojis Row */}
347	          <div className="flex flex-wrap items-center gap-1.5">
348	            <span className="text-[10px] font-mono text-[#8c7a9e] mr-1">Quick Icons:</span>
349	            {PRESET_EMOJIS.map((em) => (
350	              <button
351	                key={em}
352	                type="button"
353	                onClick={() => setEmoji(em)}
354	                className={`w-7 h-7 rounded-lg text-sm flex items-center justify-center transition border cursor-pointer ${
355	                  emoji === em ? 'bg-[#ffd86b] border-[#ffd86b] text-black shadow-gold-sm' : 'bg-[#181224] border-[#312340] hover:bg-[#251b36]'
356	                }`}
357	              >
358	                {em}
359	              </button>
360	            ))}
361	          </div>
362	
363	          {/* Channel Multi-Selection Section */}
364	          <div className="p-3.5 rounded-xl bg-[#110d1a] border border-[#2b2038] space-y-2.5">
365	            <div className="flex items-center justify-between">
366	              <span className="text-xs font-cinzel font-bold text-[#ffd86b] flex items-center gap-1.5">
367	                <Radio className="w-3.5 h-3.5" />
368	                <span>Select Member Channels *</span>
369	              </span>
370	              <span className="text-[11px] font-mono text-[#8c7a9e]">
371	                <strong className="text-white">{selectedChannels.length}</strong> selected •{' '}
372	                <strong className="text-[#ffd86b]">{totalTracksInSelection.toLocaleString()}</strong> pooled songs
373	              </span>
374	            </div>
375	
376	            {/* Channel Searcher */}
377	            <div className="relative">
378	              <Search className="w-3.5 h-3.5 text-[#8c7a9e] absolute left-3 top-1/2 -translate-y-1/2" />
379	              <input
380	                type="text"
381	                placeholder="Filter channels (e.g. Hoyo, NCS, Remix)..."
382	                value={channelSearchQuery}
383	                onChange={(e) => setChannelSearchQuery(e.target.value)}
384	                className="w-full bg-[#181224] border border-[#362747] focus:border-[#d4af37] rounded-lg pl-9 pr-3 py-1.5 text-xs text-white focus:outline-none transition placeholder-[#5e4f73]"
385	              />
386	            </div>
387	
388	            {/* Channels Checklist */}
389	            <div className="max-h-44 overflow-y-auto space-y-1 pr-1">
390	              {filteredChannels.length === 0 ? (
391	                <p className="text-xs text-[#6e5d85] italic p-2">No matching channels found</p>
392	              ) : (
393	                filteredChannels.map((ch) => {
394	                  const isChecked = selectedChannels.includes(ch.name);
395	                  return (
396	                    <button
397	                      key={ch.name}
398	                      type="button"
399	                      onClick={() => toggleChannel(ch.name)}
400	                      className={`w-full flex items-center justify-between p-2 rounded-lg text-xs font-mono transition text-left cursor-pointer border ${
401	                        isChecked
402	                          ? 'bg-[#291e0a] text-[#ffd86b] border-[#d4af37] shadow-gold-sm'
403	                          : 'bg-[#181224] text-[#b3a6c7] hover:text-white border-[#2b1f3b] hover:bg-[#201830]'
404	                      }`}
405	                    >
406	                      <div className="flex items-center gap-2 truncate">
407	                        {isChecked ? (
408	                          <CheckSquare className="w-4 h-4 text-[#ffd86b] flex-shrink-0" />
409	                        ) : (
410	                          <Square className="w-4 h-4 text-[#6e5d85] flex-shrink-0" />
411	                        )}
412	                        <span className="truncate">{ch.name}</span>
413	                      </div>
414	                      <span className="text-[10px] text-[#8c7a9e] flex-shrink-0 ml-2">
415	                        {ch.count.toLocaleString()} songs
416	                      </span>
417	                    </button>
418	                  );
419	                })
420	              )}
421	            </div>
422	          </div>
423	
424	          {/* Compatible Timeblock Arcs */}
425	          <div className="p-3.5 rounded-xl bg-[#110d1a] border border-[#2b2038] space-y-2">
426	            <span className="text-xs font-cinzel font-bold text-[#ffd86b] flex items-center gap-1.5">
427	              <Layers className="w-3.5 h-3.5" />
428	              <span>Compatible Timeblock Arcs (Optional)</span>
429	            </span>
430	            <div className="grid grid-cols-1 sm:grid-cols-2 gap-1.5">
431	              {TIMEBLOCK_OPTIONS.map((tb) => {
432	                const isActive = selectedTimeblocks.includes(tb.id);
433	                return (
434	                  <button
435	                    key={tb.id}
436	                    type="button"
437	                    onClick={() => toggleTimeblock(tb.id)}
438	                    className={`p-2 rounded-lg text-xs font-sans flex items-center gap-2 transition border cursor-pointer ${
439	                      isActive
440	                        ? 'bg-[#291e0a] text-[#ffd86b] border-[#d4af37] shadow-gold-sm'
441	                        : 'bg-[#181224] text-[#8c7a9e] hover:text-white border-[#2b1f3b]'
442	                    }`}
443	                  >
444	                    <span>{tb.emoji}</span>
445	                    <span className="truncate text-[11px]">{tb.label}</span>
446	                    {isActive && <Check className="w-3.5 h-3.5 text-[#ffd86b] ml-auto flex-shrink-0" />}
447	                  </button>
448	                );
449	              })}
450	            </div>
451	          </div>
452	
453	          {/* Footer Actions */}
454	          <div className="flex items-center justify-end gap-2 pt-2 border-t border-[#261c33]">
455	            <SharedButton variant="secondary" size="md" onClick={() => setMode('list')} disabled={isSaving}>
456	              Cancel
457	            </SharedButton>
458	            <SharedButton variant="primary" size="md" onClick={handleSave} disabled={isSaving}>
459	              {isSaving ? 'Saving...' : editingPlaylistId ? 'Update Playlist' : 'Create Playlist'}
460	            </SharedButton>
461	          </div>
462	        </div>
463	      )}
464	    </ModalContainer>
465	  );
466	};
