3	import React, { useState, useEffect, useMemo } from 'react';
4	import { useVinylStore } from '../store/useVinylStore';
5	import {
6	  fetchCustomPlaylists,
7	  fetchChannelOrigins,
8	  deleteCustomPlaylist,
9	  saveFilterConfig,
10	  fetchChannelMeta,
11	  updateChannelStatus,
12	  purgeChannelSongs,
13	} from '../services/engine';
14	import { getRankFromScore } from '../../../utils/rank';
15	import { HazardBadge } from '../../../components/HazardBadge';
16	import { SharedButton } from '../../../components/shared/SharedButton';
17	import { PlaylistManagerModal } from './PlaylistManagerModal';
18	import type { CustomPlaylist, ChannelOriginItem, ChannelStatus } from '../types';
19	import {
20	  ListMusic,
21	  Plus,
22	  Search,
23	  Play,
24	  Edit3,
25	  Trash2,
26	  Radio,
27	  Sparkles,
28	  ArrowUpDown,
29	  Crown,
30	  CheckCircle2,
31	  AlertCircle,
32	} from 'lucide-react';
33	
34	interface VinylPlaylistsProps {
35	  projectId?: string;
36	  onNavigateToGameplay?: (channelOrCustomId?: string) => void;
37	}
38	
39	export const VinylPlaylists: React.FC<VinylPlaylistsProps> = ({
40	  projectId = 'music_app',
41	  onNavigateToGameplay,
42	}) => {
43	  const targetProjectId = !projectId || projectId === 'vinyl_angel' ? 'music_app' : projectId;
44	  const {
45	    customPlaylists,
46	    setCustomPlaylists,
47	    removeCustomPlaylist,
48	    channelList,
49	    setChannelList,
50	    channelMetaMap,
51	    setChannelMetaMap,
52	    updateChannelStatus: updateChannelStatusInStore,
53	  } = useVinylStore();
54	
55	  const [loading, setLoading] = useState(true);
56	  const [activeTab, setActiveTab] = useState<'custom' | 'origins'>('custom');
57	  const [searchQuery, setSearchQuery] = useState('');
58	  const [sortBy, setSortBy] = useState<'hazard' | 'count' | 'name'>('hazard');
59	  const [statusFilter, setStatusFilter] = useState<'all' | 'approved' | 'cleaning' | 'raw'>('all');
60	  const [purgingChannelName, setPurgingChannelName] = useState<string | null>(null);
61	  const [toast, setToast] = useState<{ message: string; type?: 'info' | 'success' | 'warn' | 'error' } | null>(null);
62	
63	  const showToast = (message: string, type: 'info' | 'success' | 'warn' | 'error' = 'info') => {
64	    setToast({ message, type });
65	    setTimeout(() => setToast(null), 4000);
66	  };
67	
68	  // Modal State
69	  const [isModalOpen, setIsModalOpen] = useState(false);
70	  const [editPlaylistId, setEditPlaylistId] = useState<string | null>(null);
71	
72	  // Load playlists, channel origins, and curation metadata on mount
73	  useEffect(() => {
74	    let isCancelled = false;
75	    const loadData = async () => {
76	      setLoading(true);
77	      try {
78	        const [pls, chs, meta] = await Promise.all([
79	          fetchCustomPlaylists(targetProjectId),
80	          fetchChannelOrigins(targetProjectId),
81	          fetchChannelMeta(targetProjectId),
82	        ]);
83	        if (!isCancelled) {
84	          setCustomPlaylists(pls);
85	          setChannelList(chs);
86	          setChannelMetaMap(meta);
87	        }
88	      } catch (err) {
89	        console.error('[VinylPlaylists] Error loading data:', err);
90	      } finally {
91	        if (!isCancelled) setLoading(false);
92	      }
93	    };
94	
95	    loadData();
96	    return () => {
97	      isCancelled = true;
98	    };
99	  }, [targetProjectId, setCustomPlaylists]);
100	
101	  // Channel lookup dictionary for quick O(1) stats computation
102	  const channelLookup = useMemo(() => {
103	    const map = new Map<string, ChannelOriginItem>();
104	    channelList.forEach((ch) => map.set(ch.name, ch));
105	    return map;
106	  }, [channelList]);
107	
108	  // Compute aggregate stats for a custom playlist
109	  const getPlaylistStats = (pl: CustomPlaylist) => {
110	    let totalSongs = 0;
111	    let weightedHazardSum = 0;
112	
113	    pl.channels.forEach((chName) => {
114	      const ch = channelLookup.get(chName);
115	      if (ch) {
116	        totalSongs += ch.count;
117	        weightedHazardSum += (ch.avg_hazard ?? 3.0) * ch.count;
118	      }
119	    });
120	
121	    const avgHazard = totalSongs > 0 ? weightedHazardSum / totalSongs : 3.0;
122	    const roundedHazard = Math.round(avgHazard * 100) / 100;
123	    const rankCategory = getRankFromScore(roundedHazard);
124	
125	    return {
126	      totalSongs,
127	      avgHazard: roundedHazard,
128	      rankCategory,
129	    };
130	  };
131	
132	  // Filter and sort Custom Playlists
133	  const filteredCustomPlaylists = useMemo(() => {
134	    const q = searchQuery.toLowerCase().trim();
135	    let res = customPlaylists.filter((pl) => {
136	      if (!q) return true;
137	      const matchName = pl.name.toLowerCase().includes(q);
138	      const matchDesc = pl.description?.toLowerCase().includes(q);
139	      const matchChannel = pl.channels.some((c) => c.toLowerCase().includes(q));
140	      const matchArc = pl.compatible_timeblocks?.some((t) => t.toLowerCase().includes(q));
141	      return matchName || matchDesc || matchChannel || matchArc;
142	    });
143	
144	    if (sortBy === 'hazard') {
145	      res = [...res].sort((a, b) => getPlaylistStats(b).avgHazard - getPlaylistStats(a).avgHazard);
146	    } else if (sortBy === 'count') {
147	      res = [...res].sort((a, b) => getPlaylistStats(b).totalSongs - getPlaylistStats(a).totalSongs);
148	    } else if (sortBy === 'name') {
149	      res = [...res].sort((a, b) => a.name.localeCompare(b.name));
150	    }
151	
152	    return res;
153	  }, [customPlaylists, searchQuery, sortBy, channelLookup]);
154	
155	  // Enhanced channels with curation metadata
156	  const channelsWithMeta = useMemo(() => {
157	    return channelList.map((ch) => {
158	      const meta =
159	        channelMetaMap[ch.channel_id || ''] ||
160	        channelMetaMap[ch.name] ||
161	        { status: 'raw' as ChannelStatus };
162	      return {
163	        ...ch,
164	        status: meta.status,
165	      };
166	    });
167	  }, [channelList, channelMetaMap]);
168	
169	  // Filter and sort Raw Channel Origins with Manager's Triple-Priority Order:
170	  // 1. Status: Approved -> Cleaning -> Raw
171	  // 2. Hazard Level: High to Low
172	  // 3. Number of songs: High to Low
173	  const filteredOriginChannels = useMemo(() => {
174	    const q = searchQuery.toLowerCase().trim();
175	    let res = channelsWithMeta.filter((ch) => {
176	      const matchSearch =
177	        !q ||
178	        ch.name.toLowerCase().includes(q) ||
179	        (ch.best_title && ch.best_title.toLowerCase().includes(q));
180	      const matchStatus = statusFilter === 'all' || ch.status === statusFilter;
181	      return matchSearch && matchStatus;
182	    });
183	
184	    const statusWeight = (s?: ChannelStatus) => {
185	      if (s === 'approved') return 1;
186	      if (s === 'cleaning') return 2;
187	      return 3; // 'raw'
188	    };
189	
190	    res.sort((a, b) => {
191	      // 1. Status Priority: Approved (1) -> Cleaning (2) -> Raw (3)
192	      const sA = statusWeight(a.status);
193	      const sB = statusWeight(b.status);
194	      if (sA !== sB) return sA - sB;
195	
196	      // 2. Hazard Level: High to Low
197	      const hA = a.avg_hazard ?? 3.0;
198	      const hB = b.avg_hazard ?? 3.0;
199	      if (Math.abs(hA - hB) > 0.001) return hB - hA;
200	
201	      // 3. Number of songs: High to Low
202	      return b.count - a.count;
203	    });
204	
205	    return res;
206	  }, [channelsWithMeta, searchQuery, statusFilter]);
207	
208	  const handleCycleStatus = async (ch: ChannelOriginItem, e: React.MouseEvent) => {
209	    e.stopPropagation();
210	    const current = ch.status || 'raw';
211	    const next: ChannelStatus =
212	      current === 'raw' ? 'cleaning' : current === 'cleaning' ? 'approved' : 'raw';
213	
214	    // Optimistic update in shared store (propagates to all tabs immediately)
215	    updateChannelStatusInStore(ch.channel_id || ch.name, ch.name, next);
216	
217	    try {
218	      await updateChannelStatus(targetProjectId, ch.channel_id || '', ch.name, next);
219	      showToast(`Set "${ch.name}" status to ${next.toUpperCase()}`, 'success');
220	    } catch (err) {
221	      showToast(`Failed to update status for ${ch.name}`, 'error');
222	    }
223	  };
224	
225	  const handlePurgeChannel = async (ch: ChannelOriginItem, e: React.MouseEvent) => {
226	    e.stopPropagation();
227	    const confirmed = window.confirm(
228	      `⚠️ PERMANENT PURGE WARNING\n\nDelete all ${ch.count.toLocaleString()} songs of "${ch.name}"?\n\nThis completely removes all tracks of this channel from Tier 1, 3, and 4 so you can re-ingest clean curated playlists.\n\nProceed?`
229	    );
230	    if (!confirmed) return;
231	
232	    setPurgingChannelName(ch.name);
233	    try {
234	      const res = await purgeChannelSongs(targetProjectId, ch.name, ch.channel_id);
235	      if (res.success) {
236	        showToast(
237	          `🗑️ Purged ${res.purged_count.toLocaleString()} songs from "${ch.name}". Channel cleared!`,
238	          'success'
239	        );
240	        // Derived existence: remove channel from local state immediately
241	        setChannelList(channelList.filter((c) => c.name !== ch.name));
242	      } else {
243	        showToast(`Purge skipped: no tracks found for "${ch.name}"`, 'warn');
244	      }
245	    } catch (err: any) {
246	      showToast(`Failed to purge "${ch.name}": ${err.message}`, 'error');
247	    } finally {
248	      setPurgingChannelName(null);
249	    }
250	  };
251	
252	  // Direct play handler: sets selected channel in config and navigates to gameplay
253	  const handlePlaySource = async (sourceValue: string) => {
254	    useVinylStore.getState().setQueuedPlaylistForGameplay(sourceValue);
255	    await saveFilterConfig(targetProjectId, {
256	      excludedChannels: [],
257	      selectedChannel: sourceValue,
258	    });
259	    if (onNavigateToGameplay) {
260	      onNavigateToGameplay(sourceValue);
261	    }
262	  };
263	
264	  const handleOpenCreateModal = () => {
265	    setEditPlaylistId(null);
266	    setIsModalOpen(true);
267	  };
268	
269	  const handleOpenEditModal = (plId: string) => {
270	    setEditPlaylistId(plId);
271	    setIsModalOpen(true);
272	  };
273	
274	  const handleDeletePlaylist = async (plId: string) => {
275	    if (!confirm('Are you sure you want to delete this custom playlist?')) return;
276	    try {
277	      await deleteCustomPlaylist(targetProjectId, plId);
278	      removeCustomPlaylist(plId);
279	    } catch (err) {
280	      console.error('Failed to delete playlist:', err);
281	    }
282	  };
283	
284	  return (
285	    <div className="space-y-6 text-left">
286	      {/* Toast Notification */}
287	      {toast && (
288	        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 px-5 py-3 rounded-xl bg-[#171320] border border-[#d4af37] text-xs font-semibold shadow-2xl flex items-center gap-2 animate-in fade-in slide-in-from-bottom-2 text-[#ffd86b] max-w-lg">
289	          {toast.type === 'success' && <CheckCircle2 className="w-4 h-4 text-emerald-400 flex-shrink-0" />}
290	          {toast.type === 'error' && <AlertCircle className="w-4 h-4 text-rose-400 flex-shrink-0" />}
291	          {toast.type === 'warn' && <AlertCircle className="w-4 h-4 text-amber-400 flex-shrink-0" />}
292	          {toast.type === 'info' && <Sparkles className="w-4 h-4 text-[#ffd86b] flex-shrink-0" />}
293	          <span>{toast.message}</span>
294	        </div>
295	      )}
296	
297	      {/* Top Banner & Action */}
298	      <div className="p-6 md:p-8 rounded-2xl bg-[#120f18] border border-[#2b2238] shadow-2xl relative overflow-hidden flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
299	        <div className="space-y-1.5 z-10 max-w-xl">
300	          <div className="flex items-center gap-2">
301	            <span className="p-2 rounded-xl bg-amber-950/60 border border-amber-600/50 text-[#ffd86b]">
302	              <ListMusic className="w-5 h-5" />
303	            </span>
304	            <span className="font-cinzel text-xs font-bold text-[#ffd86b] tracking-wider uppercase">
305	              Harmonic Playlists &amp; Federations
