556	      };
557	    }
558	    const r = stateMap[evt.id];
559	    if (evt.hazard_rank !== undefined && evt.hazard_rank !== null) {
560	      r.hazard_rank = Number(evt.hazard_rank);
561	    }
562	
563	    if (act === '3+' || act === 'cancel' || act === 'downvote') {
564	      r.score_3_count.push(evt.timestamp);
565	    } else if (act === '4+') {
566	      r.score_4_count.push(evt.timestamp);
567	    } else if (act === '5+' || act === 'continue') {
568	      r.score_5_count.push(evt.timestamp);
569	    } else if (act === '6+' || act === 'upvote') {
570	      r.score_6_count.push(evt.timestamp);
571	    } else if (act === '7+' || act === 'overflow') {
572	      r.score_7_count.push(evt.timestamp);
573	    }
574	
575	    if (evt.timeblock) {
576	      const blocks = Array.isArray(evt.timeblock) ? evt.timeblock : [evt.timeblock];
577	      blocks.forEach((b) => {
578	        if (/arc\s*zero|kick/i.test(b)) r.timeblock_arc0++;
579	        else if (/arc\s*0?1|morning/i.test(b)) r.timeblock_arc1++;
580	        else if (/arc\s*0?2|battle/i.test(b)) r.timeblock_arc2++;
581	        else if (/arc\s*0?3|night/i.test(b)) r.timeblock_arc3++;
582	        else if (/arc\s*0?4|sacred/i.test(b)) r.timeblock_arc4++;
583	      });
584	    }
585	    modifiedTrackIds.add(evt.id);
586	  }
587	
588	  // 7. Upsert modified track states into tier_3_data
589	  if (modifiedTrackIds.size > 0) {
590	    const t3BatchData: Record<string, Record<string, unknown>> = {};
591	    for (const id of modifiedTrackIds) {
592	      if (excludedSet.has(id)) continue;
593	      const r = stateMap[id];
594	      t3BatchData[id] = {
595	        score_3_count: JSON.stringify(r.score_3_count),
596	        score_4_count: JSON.stringify(r.score_4_count),
597	        score_5_count: JSON.stringify(r.score_5_count),
598	        score_6_count: JSON.stringify(r.score_6_count),
599	        score_7_count: JSON.stringify(r.score_7_count),
600	        timeblock_arc0: r.timeblock_arc0,
601	        timeblock_arc1: r.timeblock_arc1,
602	        timeblock_arc2: r.timeblock_arc2,
603	        timeblock_arc3: r.timeblock_arc3,
604	        timeblock_arc4: r.timeblock_arc4,
605	        unlock_date: r.unlock_date,
606	        hazard_rank: r.hazard_rank ?? null,
607	      };
608	    }
609	
610	    await executeOrder({
611	      project_id: projectId,
612	      tier: '3',
613	      order: {
614	        action: 'batch_upsert',
615	        data: t3BatchData,
616	      },
617	    });
618	  }
619	
620	  // 8. Upsert modified channel states into channel_state table
621	  if (modifiedChannelIds.size > 0) {
622	    const chBatchData: Record<string, Record<string, unknown>> = {};
623	    for (const chId of modifiedChannelIds) {
624	      const ch = channelMap[chId];
625	      chBatchData[chId] = {
626	        channel_id: ch.channel_id,
627	        channel_name: ch.channel_name,
628	        score_3_count: JSON.stringify(ch.score_3_count),
629	        score_4_count: JSON.stringify(ch.score_4_count),
630	        score_5_count: JSON.stringify(ch.score_5_count),
631	        score_6_count: JSON.stringify(ch.score_6_count),
632	        score_7_count: JSON.stringify(ch.score_7_count),
633	        timeblock_arc0: ch.timeblock_arc0,
634	        timeblock_arc1: ch.timeblock_arc1,
635	        timeblock_arc2: ch.timeblock_arc2,
636	        timeblock_arc3: ch.timeblock_arc3,
637	        timeblock_arc4: ch.timeblock_arc4,
638	        unlock_date: ch.unlock_date,
639	        updated_at: new Date().toISOString(),
640	      };
641	    }
642	
643	    await executeOrder({
644	      project_id: projectId,
645	      tier: 'channel_state',
646	      order: {
647	        action: 'batch_upsert',
648	        data: chBatchData,
649	      },
650	    });
651	  }
652	
653	  // Clear _2_events.jsonl whenever events have been processed into Tier 3
654	  if (rawEvents.length > 0 && (forceClear || rawEvents.length >= 15)) {
655	    await executeOrder({ project_id: projectId, tier: '2', order: { action: 'clear' } });
656	  }
657	
658	  return {
659	    eventsProcessed: rawEvents.length,
660	    updatedTracksCount: modifiedTrackIds.size,
661	    updatedChannelsCount: modifiedChannelIds.size,
662	    blockedCount: blockedIds.length,
663	    staticSynced: true,
664	  };
665	}
