667	export async function syncTier3ToTier4(projectId: string) {
668	  const [t3Records, channelRecords] = await Promise.all([
669	    fetchTier3State(projectId),
670	    fetchChannelState(projectId),
671	  ]);
672	
673	  const t4ValidBatchMap: Record<string, Record<string, unknown>> = {};
674	
675	  // Index individual track ratings
676	  const trackMap: Record<string, Tier3StateRecord> = {};
677	  for (const t3 of t3Records) {
678	    trackMap[t3.id] = t3;
679	  }
680	
681	  // Fetch track lists for rated channels to apply channel-wide metadata
682	  const activeChannelIds = Object.keys(channelRecords);
683	  const channelTracksMap: Record<string, string[]> = {};
684	
685	  if (activeChannelIds.length > 0) {
686	    try {
687	      const chTracksRes = await executeOrder<Record<string, string[]>>({
688	        project_id: projectId,
689	        tier: '1',
690	        order: {
691	          action: 'get_channel_tracks',
692	          data: { channel_ids: activeChannelIds },
693	        },
694	      });
695	      if (chTracksRes.data) {
696	        Object.assign(channelTracksMap, chTracksRes.data);
697	      }
698	    } catch (e) {
699	      console.warn('[syncTier3ToTier4] Error fetching channel tracks:', e);
700	    }
701	  }
702	
703	  const processedSongIds = new Set<string>();
704	
705	  // Process all songs belonging to rated channels (channel metadata applies to every song of that channel)
706	  for (const chId of activeChannelIds) {
707	    const ch = channelRecords[chId];
708	    const songsInChannel = channelTracksMap[chId] || [];
709	
710	    for (const songId of songsInChannel) {
711	      processedSongIds.add(songId);
712	
713	      const individualT3 = trackMap[songId];
714	      let compositeRecord: Tier3StateRecord;
715	
716	      if (individualT3) {
717	        compositeRecord = {
718	          id: songId,
719	          score_3_count: [...ch.score_3_count, ...individualT3.score_3_count],
720	          score_4_count: [...ch.score_4_count, ...individualT3.score_4_count],
721	          score_5_count: [...ch.score_5_count, ...individualT3.score_5_count],
722	          score_6_count: [...ch.score_6_count, ...individualT3.score_6_count],
723	          score_7_count: [...ch.score_7_count, ...individualT3.score_7_count],
724	          timeblock_arc0: ch.timeblock_arc0 + individualT3.timeblock_arc0,
725	          timeblock_arc1: ch.timeblock_arc1 + individualT3.timeblock_arc1,
726	          timeblock_arc2: ch.timeblock_arc2 + individualT3.timeblock_arc2,
727	          timeblock_arc3: ch.timeblock_arc3 + individualT3.timeblock_arc3,
728	          timeblock_arc4: ch.timeblock_arc4 + individualT3.timeblock_arc4,
729	          unlock_date: individualT3.unlock_date || ch.unlock_date,
730	          hazard_rank: individualT3.hazard_rank ?? null,
731	        };
732	      } else {
733	        compositeRecord = {
734	          id: songId,
735	          score_3_count: [...ch.score_3_count],
736	          score_4_count: [...ch.score_4_count],
737	          score_5_count: [...ch.score_5_count],
738	          score_6_count: [...ch.score_6_count],
739	          score_7_count: [...ch.score_7_count],
740	          timeblock_arc0: ch.timeblock_arc0,
741	          timeblock_arc1: ch.timeblock_arc1,
742	          timeblock_arc2: ch.timeblock_arc2,
743	          timeblock_arc3: ch.timeblock_arc3,
744	          timeblock_arc4: ch.timeblock_arc4,
745	          unlock_date: ch.unlock_date,
746	          hazard_rank: null,
747	        };
748	      }
749	
750	      if (compositeRecord.hazard_rank) {
751	        const hazard = calculateHazardLevel(compositeRecord);
752	        t4ValidBatchMap[songId] = {
753	          id: songId,
754	          hazard_level: hazard,
755	          played: calculateTotalPlayed(compositeRecord),
756	          timeblock: getDominantTimeblock(compositeRecord),
757	          unlock_date: compositeRecord.unlock_date,
758	        };
759	      }
760	    }
761	  }
762	
763	  // Process remaining individual track ratings whose channels weren't batch rated
764	  for (const t3 of t3Records) {
765	    if (processedSongIds.has(t3.id)) continue;
766	
767	    if (t3.hazard_rank) {
768	      const hazard = calculateHazardLevel(t3);
769	      t4ValidBatchMap[t3.id] = {
770	        id: t3.id,
771	        hazard_level: hazard,
772	        played: calculateTotalPlayed(t3),
773	        timeblock: getDominantTimeblock(t3),
774	        unlock_date: t3.unlock_date,
775	      };
776	    }
777	  }
778	
779	  if (Object.keys(t4ValidBatchMap).length > 0) {
780	    await executeOrder({
781	      project_id: projectId,
782	      tier: '4',
783	      order: {
784	        action: 'batch_upsert',
785	        data: t4ValidBatchMap,
786	      },
787	    });
788	  }
789	
790	  invalidateVinylCache(projectId);
791	  return {
792	    syncedCount: Object.keys(t4ValidBatchMap).length,
793	    purgedCount: 0,
794	    badKpiIds: [],
795	  };
796	}
