1071	  channelName?: string,
1072	  hazardCap?: number | string | null,
1073	  excludeChannel?: string | string[] | null,
1074	  channels?: string[] | null,
1075	  blockedIds?: string[] | null  // NEW: immediately excluded blocked song IDs
1076	): Promise<{
1077	  tracks: PlaylistItem[];
1078	  totalCatalogCount: number;
1079	  statsMap: Record<string, import('../types').TrackDisplayMeta>;
1080	}> {
1081	  const samplePayload: any = { limit };
1082	  if (channels && channels.length > 0) {
1083	    samplePayload.channels = channels;
1084	  } else if (channelName && channelName !== 'ALL') {
1085	    samplePayload.channel_name = channelName;
1086	  }
1087	  if (excludeChannel && excludeChannel !== 'NONE' && excludeChannel !== 'ALL') {
1088	    samplePayload.exclude_channel = excludeChannel;
1089	  }
1090	  if (hazardCap !== undefined && hazardCap !== null && hazardCap !== 'ALL' && hazardCap !== 'NONE') {
1091	    samplePayload.hazard_cap = hazardCap;
1092	  }
1093	  // NEW: Pass blocked song IDs for immediate exclusion from pool
1094	  if (blockedIds && blockedIds.length > 0) {
1095	    samplePayload.exclude_ids = blockedIds;
1096	  }
1097	
1098	  const countPayload: any = {};
1099	  if (channels && channels.length > 0) {
1100	    countPayload.channels = channels;
1101	  } else if (channelName && channelName !== 'ALL') {
1102	    countPayload.channel_name = channelName;
1103	  }
1104	  if (excludeChannel && excludeChannel !== 'NONE' && excludeChannel !== 'ALL') {
1105	    countPayload.exclude_channel = excludeChannel;
1106	  }
1107	  if (hazardCap !== undefined && hazardCap !== null && hazardCap !== 'ALL' && hazardCap !== 'NONE') {
1108	    countPayload.hazard_cap = hazardCap;
1109	  }
1110	  if (blockedIds && blockedIds.length > 0) {
1111	    countPayload.exclude_ids = blockedIds;
1112	  }
1113	
1114	  const [sampleRes, countRes, t4Res, channelStateMap] = await Promise.all([
1115	    executeOrder<Record<string, Record<string, unknown>>>({
1116	      project_id: projectId,
1117	      tier: '1',
1118	      order: { action: 'sample', data: samplePayload },
1119	    }),
1120	    executeOrder<{ count: number }>({
1121	      project_id: projectId,
1122	      tier: '1',
1123	      order: { action: 'count', data: countPayload },
1124	    }),
1125	    executeOrder<Record<string, Record<string, unknown>>>({
1126	      project_id: projectId,
1127	      tier: '4',
1128	      order: { action: 'read_all' },
1129	    }),
1130	    fetchChannelState(projectId),
1131	  ]);
1132	
1133	  const statsMap: Record<string, import('../types').TrackDisplayMeta> = {};
1134	  if (t4Res.data) {
1135	    Object.entries(t4Res.data).forEach(([id, val]) => {
1136	      let played = 0;
1137	      let hazard_level = 3.0;
1138	      let timeblock: string | null = null;
1139	      let unlock_date: string | null = null;
1140	
1141	      if (val && typeof val === 'object' && !Array.isArray(val)) {
1142	        const v = val as Record<string, unknown>;
1143	        played = Number.isInteger(v.played)
1144	          ? (v.played as number)
1145	          : parseInt(String(v.played || 0), 10);
1146	        const rawHazard = Number(v.hazard_level);
1147	        hazard_level = !isNaN(rawHazard) ? rawHazard : 3.0;
1148	        timeblock = (v.timeblock as string) || null;
1149	        unlock_date = (v.unlock_date as string) || null;
1150	      } else if (val !== null && val !== undefined) {
1151	        played = parseInt(String(val), 10);
1152	      }
1153	
1154	      statsMap[String(id)] = {
1155	        played: Number.isFinite(played) && played >= 0 ? Math.floor(played) : 0,
