1474	export async function streamPlaylistIngestion(
1475	  options: {
1476	    urls?: string[];
1477	    max_playlists?: number;
1478	    max_per_playlist?: number;
1479	  },
1480	  onEvent: (event: CurlerStreamEvent) => void,
1481	  signal?: AbortSignal
1482	): Promise<void> {
1483	  const res = await fetch(`${API_BASE}/api/v1/curler/stream`, {
1484	    method: 'POST',
1485	    headers: { 'Content-Type': 'application/json' },
1486	    body: JSON.stringify(options),
1487	    signal,
1488	  });
1489	
1490	  if (!res.ok) {
1491	    throw new Error(`Curler stream request failed with HTTP ${res.status}`);
1492	  }
1493	
1494	  if (!res.body) {
1495	    throw new Error('ReadableStream not supported on response body.');
1496	  }
1497	
1498	  const reader = res.body.getReader();
1499	  const decoder = new TextDecoder('utf-8');
1500	  let buffer = '';
1501	
1502	  while (true) {
1503	    const { done, value } = await reader.read();
1504	    if (done) break;
1505	
1506	    buffer += decoder.decode(value, { stream: true });
1507	    const chunks = buffer.split('\n\n');
1508	    buffer = chunks.pop() || '';
1509	
1510	    for (const chunk of chunks) {
1511	      const trimmed = chunk.trim();
1512	      if (trimmed.startsWith('data:')) {
1513	        try {
1514	          const jsonStr = trimmed.slice(5).trim();
1515	          if (jsonStr) {
1516	            const eventData = JSON.parse(jsonStr) as CurlerStreamEvent;
1517	            onEvent(eventData);
1518	          }
1519	        } catch (err) {
1520	          console.warn('[Curler Stream] Failed to parse SSE chunk:', err);
1521	        }
1522	      }
1523	    }
1524	  }
1525	
1526	  if (buffer.trim().startsWith('data:')) {
1527	    try {
1528	      const jsonStr = buffer.trim().slice(5).trim();
1529	      if (jsonStr) {
1530	        const eventData = JSON.parse(jsonStr) as CurlerStreamEvent;
1531	        onEvent(eventData);
1532	      }
1533	    } catch (_) {}
1534	  }
1535	
1536	  // Clear static caches after streaming completes
1537	  for (const k in tier1MemoryCache) delete tier1MemoryCache[k];
1538	  invalidateVinylCache();
1539	}
