1671	// [SOVEREIGN HAZARD RANK ENGINE ASSIGNMENT]
1672	// Sets or retrieves the Manager's personal explicit hazard_rank (3 to 7) in _3_state.db
1673	// =============================================================================
1674	export async function updateTrackHazardRank(
1675	  projectId: string,
1676	  trackId: string,
1677	  hazardRank: number
1678	): Promise<{ success: boolean; newHazard: number }> {
1679	  try {
1680	    // 1. Fetch current Tier 3 counts if any
1681	    let s5 = 0;
1682	    let s6 = 0;
1683	    let s7 = 0;
1684	    try {
1685	      const curT3 = await executeOrder<Record<string, unknown>>({
1686	        project_id: projectId,
1687	        tier: '3',
1688	        order: { action: 'read_key', key: trackId },
1689	      });
1690	      if (curT3.data) {
1691	        const parseCount = (v: unknown) => {
1692	          if (Array.isArray(v)) return v.length;
1693	          if (typeof v === 'string') {
1694	            try {
1695	              const parsed = JSON.parse(v);
1696	              return Array.isArray(parsed) ? parsed.length : 0;
1697	            } catch {
1698	              return 0;
1699	            }
1700	          }
1701	          return 0;
1702	        };
1703	        s5 = parseCount(curT3.data.score_5_count);
1704	        s6 = parseCount(curT3.data.score_6_count);
1705	        s7 = parseCount(curT3.data.score_7_count);
1706	      }
1707	    } catch (_) {}
1708	
1709	    // Sovereign formula: Base = rank - 0.5, k = (8.5 - rank) / 100, S = 4*s7 + 2*s6 + 1*s5
1710	    const base = hazardRank - 0.5;
1711	    const k = (8.5 - hazardRank) / 100.0;
1712	    const S = 4 * s7 + 2 * s6 + 1 * s5;
1713	    const newHazard = Math.round(Math.min(8.5, Math.max(1.0, base + k * S)) * 100) / 100;
1714	
1715	    // 2. Persist hazard_rank to _3_state.db (Tier 3)
1716	    await executeOrder({
1717	      project_id: projectId,
1718	      tier: '3',
1719	      order: {
1720	        action: 'upsert',
1721	        key: trackId,
1722	        data: {
1723	          hazard_rank: hazardRank,
1724	        },
1725	      },
1726	    });
1727	
1728	    // 3. Immediately project new hazard_level to _4_display.db (Tier 4)
1729	    await executeOrder({
1730	      project_id: projectId,
1731	      tier: '4',
1732	      order: {
1733	        action: 'upsert',
1734	        key: trackId,
1735	        data: {
1736	          hazard_level: newHazard,
1737	        },
1738	      },
1739	    });
1740	
1741	    return { success: true, newHazard };
1742	  } catch (err) {
1743	    console.error(`[Engine] Failed to update hazard_rank for track ${trackId}:`, err);
1744	    throw err;
1745	  }
1746	}
